input.sparql:
SELECT ?zone ?label ?sensor ?sclass ?tsid WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?label .
  FILTER(?label = "DataCenter_bot_ZN_6")
  ?zone brick:hasPoint ?sensor .
}

SELECT ?p ?class ?label ?tsid WHERE {
  ?p a ?class . ?p rdfs:label ?label .
  ?zone a brick:Zone . ?zone brick:hasPoint ?p .
  FILTER(?zone = URI("http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z07"))
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
}

SELECT ?p ?class ?label ?tsid WHERE {
  ?q a brick:Zone . ?q brick:hasPoint ?p .
} LIMIT 200

SELECT ?cls ?count WHERE {
  ?s a ?cls .
} GROUP BY ?cls ORDER BY ?cls LIMIT 100

SELECT ?p ?label ?islight ?tsid WHERE {
  ?p a brick:Electric_Power_Sensor .
  OPTIONAL { ?p rdfs:label ?label }
  OPTIONAL { ?p brick:hasProperty ?islight }
} LIMIT 200

SELECT ?zone ?p ?label WHERE {
  ?zone a brick:HVAC_Zone .
  ?zone brick:hasPoint ?p .
  OPTIONAL { ?p rdfs:label ?label }
}
